 assert_eq!(f.queries.db.stats(finite::REACTIVE_RESULT).computed,5,"three read children plus dependency and one canonical facts job");let computed=f.queries.db.stats(finite::REACTIVE_RESULT).computed;let old_policy=f.queries.db.value_bytes_at(policy);f.get(Request::Dependencies,|_|Ok(())).unwrap();assert_eq!(f.queries.db.stats(finite::REACTIVE_RESULT).computed,computed);assert_eq!(f.queries.db.value_bytes_at(policy),old_policy);assert_eq!(f.reads.load(Ordering::Relaxed),before);
