#[test]fn shared_policy_loan_requires_one_current_owner_and_preserves_operational_priority(){
 let f=Fixture::new();let foreign=Fixture::new();
 f.get(Fixture::read("leaf"),|_|{let p=f.policy_params();let value=f.queries.db.get::<Result<Value,String>>(p.key,Arc::new(p)).unwrap();let Value::PolicyFacts(data)=value.as_ref().as_ref().unwrap()else{panic!("actual shared facts")};let poll=||crate::daemon::control::checkpoint();
  let omitted=|_:&mut dyn FnMut(&reads::UnsealedPolicyFacts)->Result<(),Failure>|Ok(());assert!(matches!(reads::with_policy_data(&omitted,f.capture.policy(),&poll,|_|Ok(())),Err(Failure::Operational(ref actual))if actual.kind()==io::ErrorKind::InvalidInput));
  let repeated=|consume:&mut dyn FnMut(&reads::UnsealedPolicyFacts)->Result<(),Failure>|{let _=consume(&data.data);let _=consume(&data.data);Ok(())};assert!(matches!(reads::with_policy_data(&repeated,f.capture.policy(),&poll,|_|Ok(())),Err(Failure::Operational(ref actual))if actual.kind()==io::ErrorKind::InvalidInput));
  let valid=|consume:&mut dyn FnMut(&reads::UnsealedPolicyFacts)->Result<(),Failure>|consume(&data.data);assert!(matches!(reads::with_policy_data(&valid,foreign.capture.policy(),&poll,|_|Ok(())),Err(Failure::Operational(ref actual))if actual.kind()==io::ErrorKind::InvalidInput));
  let late_io=|consume:&mut dyn FnMut(&reads::UnsealedPolicyFacts)->Result<(),Failure>|{let _=consume(&data.data);Err(Failure::Operational(io::Error::from_raw_os_error(1450)))};assert!(matches!(reads::with_policy_data(&late_io,f.capture.policy(),&poll,|_|Err::<(),_>(Failure::Unsupported("semantic consumer refusal".into()))),Err(Failure::Operational(ref actual))if actual.raw_os_error()==Some(1450)));
  let token=crate::daemon::control::Cancellation::default();let binding=crate::daemon::control::bind_with_deadline(token.clone(),Instant::now()+Duration::from_secs(30));let late_cancel=|consume:&mut dyn FnMut(&reads::UnsealedPolicyFacts)->Result<(),Failure>|{let _=consume(&data.data);token.cancel();Ok(())};assert!(matches!(reads::with_policy_data(&late_cancel,f.capture.policy(),&poll,|_|Err::<(),_>(Failure::Unsupported("semantic before cancellation".into()))),Err(Failure::Operational(ref actual))if actual.kind()==io::ErrorKind::Interrupted));drop(binding);
  reads::with_policy_data(&valid,f.capture.policy(),&poll,|value|{assert!(value.tracked_names().any(|name|name=="charge"));Ok(())}).map_err(|failure|match failure{Failure::Operational(actual)=>actual,Failure::Unsupported(message)=>io::Error::new(io::ErrorKind::Unsupported,message)})?;Ok(())
 }).unwrap();
}

