 assert_eq!(f.queries.db.stats(super::super::super::body_syntax::BODY_SYNTAX).computed,3,"only demanded draw/UI children; raw-derived scanner and header/test requests add no unrelated body");assert_eq!(f.reads.load(Ordering::Relaxed),before);assert!(f.queries.raw_policy.admission.workspace_operation.lock().unwrap().is_none());
