#[test]
fn published_workspace_retains_one_real_generator_child_and_reuses_artifact_without_io_or_body_parse(){
 use generator_policy::GeneratorName as G;
 let f=Fixture::new_generator_with_configuration("tools/ci/lint_scopes.toml");
 let child=f._snapshot.workspace_generator_inputs(crate::GeneratorName::Deps).unwrap();
 assert!(Arc::ptr_eq(child,f._snapshot.workspace_generator_inputs(crate::GeneratorName::Deps).unwrap()));assert!(f._snapshot.workspace_generator_inputs(crate::GeneratorName::Reads).is_err(),"known but unrequested generator cannot borrow the snapshot child");
 assert_eq!(f._snapshot.policy_revision,Some(f.workspace.policy_revision()));
 assert_ne!(child.policy_revision(),f._snapshot.policy_revision,"subset intent is not published workspace authority");
 let compiled=child.policy().file(&f.workspace.root().join("code/probe.dm")).unwrap();
 assert!(compiled.is_compiled());
 assert!(compiled.view(dm_analysis::policy_inputs::TextView::CompilerDecoded).is_ok());
 assert!(compiled.view(dm_analysis::policy_inputs::TextView::AnalyzeRaw).is_err(),"unused compiled raw normalization must not be retained");
 assert!(child.policy().file(&f.workspace.root().join("deepquarry.dme")).unwrap().view(dm_analysis::policy_inputs::TextView::AnalyzeRaw).is_ok());
 let before=f.reads.load(Ordering::Relaxed);
 let first=f.queries.with_workspace_generator(&f.workspace,&f.scope,child,G::Deps,|artifact|Ok(artifact.text().as_ptr()as usize)).unwrap();
 let bodies=f.queries.db.stats(super::super::super::body_syntax::BODY_SYNTAX).computed;
 let artifacts=f.queries.db.stats(generator_policy::GENERATOR_RESULT).computed;
 let second=f.queries.with_workspace_generator(&f.workspace,&f.scope,f._snapshot.workspace_generator_inputs(crate::GeneratorName::Deps).unwrap(),G::Deps,|artifact|Ok(artifact.text().as_ptr()as usize)).unwrap();
 assert_eq!(first,second);assert_eq!(f.queries.db.stats(generator_policy::GENERATOR_RESULT).computed,artifacts);
 assert_eq!(f.queries.db.stats(super::super::super::body_syntax::BODY_SYNTAX).computed,bodies);
 assert_eq!(f.reads.load(Ordering::Relaxed),before);
}
