 let mut f=Fixture::new_generator();let other=Fixture::new_generator();
 let old=Arc::clone(f._snapshot.workspace_generator_inputs(crate::GeneratorName::Deps).unwrap());let old_scope=Arc::clone(&f.scope);
 let error=f.queries.with_workspace_generator(&f.workspace,&f.scope,other._snapshot.workspace_generator_inputs(crate::GeneratorName::Deps).unwrap(),G::Deps,|_|->io::Result<()>{panic!("foreign frame cannot deliver")}).unwrap_err();
 assert!(matches!(error.kind(),io::ErrorKind::Other|io::ErrorKind::InvalidData|io::ErrorKind::InvalidInput));
 f.change_uncompiled_marker();
 let current=f._snapshot.workspace_generator_inputs(crate::GeneratorName::Deps).unwrap();assert!(!Arc::ptr_eq(&old,current));
 assert!(f.queries.with_workspace_generator(&f.workspace,&old_scope,&old,G::Deps,|_|->io::Result<()>{panic!("retired scope cannot deliver")}).is_err());
